enum FileType {
    FRAG_SHADER     = 0,
    VERT_SHADER     = 1,
    IMAGE           = 2,
    GEOMETRY        = 3,
    CUBEMAP         = 4,
    GLSL_DEPENDENCY = 5,
    IMAGE_BUMPMAP   = 6
};

struct WatchFile {
    std::string path;
    FileType    type;
    int         lastChange;
    bool        vFlip;      // Use for textures to know if they should be flipped or not
};

struct Command {
    Command() {}

    Command(const std::string &_trigger, std::function<bool(const std::string&)> _do, const std::string &_formula, const std::string &_description, bool _mutex = true) {
        trigger = _trigger;
        exec = _do;
        formula = _formula;
        description = _description;
        mutex = _mutex;
    }

    std::string                             trigger;
    std::string                             formula;
    std::string                             description;
    std::function<bool(const std::string&)> exec;
    bool                                    mutex;
};

struct StatSample {
    double       startMs;
    double       endMs;
    double       durationMs;
};

struct StatTrack {
    std::string             stack;
    StatPoint               start;
    std::vector<StatSample> samples;
    double                  durationAverage;
};

class Tracker {
public:
    Tracker();
    virtual ~Tracker();

    void    start();
    void    stop();

    void    begin(const std::string& _track);
    void    end(const std::string& _track);

    double  getFramerate();

    std::string logSamples();
    std::string logSamples(const std::string& _track);
    std::string logAverage();
    std::string logAverage(const std::string& _track);
    std::string logFramerate();

    bool    isRunning() const { return m_running; }

protected:

    double                  m_trackerStart;

    std::vector<std::string>            m_tracks;
    std::map<std::string, StatTrack>    m_data;

    bool                    m_running = false;

};

